'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={answer_key:'Answer key correction',stem_data:'Missing question data',option_repair:'Incomplete option',spelling:'Spelling correction',exam_reference:'Exam reference cleanup',markup_leak:'Math rendering correction',identical_options:'Duplicate answer options',solution_fix:'Solution correction',type_mismatch:'Question type correction',wrong_chapter:'Chapter classification',answer_form:'Answer unit clarification',diagram:'Missing diagram',syllabus:'Syllabus confirmation',unsound:'No valid answer option',no_error:'Answer checked and correct',already_fixed:'Already corrected',display_issue:'Display or loading issue',app_issue:'Answer recording issue',language_mode:'Language request',not_actionable:'More detail needed'};
let data,cases=[],selected,filter='all',view='queue',pendingAction,busy=false;
let actor=localStorage.getItem('acadza-reviewer')||'',token=sessionStorage.getItem('acadza-token')||'';
function safeHTML(source){
 const doc=new DOMParser().parseFromString(String(source||''),'text/html');
 const allowed=new Set('body p div span h1 h2 h3 h4 br b strong em i u sub sup table tbody tr td th ol ul li math mstyle mrow mi mn mo mfrac msup msub msubsup msqrt mroot mtext mspace mfenced mover munder munderover mtable mtr mtd menclose semantics annotation img'.split(' '));
 function clean(node){for(const el of [...node.children]){const name=el.localName.toLowerCase();if(['script','style','iframe','object','embed','svg','link','meta','form','input','button','annotation-xml'].includes(name)){el.remove();continue}if(!allowed.has(name)){clean(el);el.replaceWith(...el.childNodes);continue}for(const a of [...el.attributes]){if(!['xmlns','display','mathvariant','displaystyle','stretchy','fence','form','width','height','columnalign','rowspan','colspan','src','alt'].includes(a.name))el.removeAttribute(a.name);if(a.name==='src'&&!/^https:\/\//i.test(a.value))el.removeAttribute('src');}if(name==='img'){el.setAttribute('loading','lazy');el.setAttribute('referrerpolicy','no-referrer')}clean(el)}}
 clean(doc.body);return doc.body.innerHTML;
}
function text(html){return new DOMParser().parseFromString(html,'text/html').body.textContent.replace(/\s+/g,' ').trim()}
function title(c){const t=text(c.q[c.q.questionType].question).split('(A)')[0];return t.length>115?t.slice(0,112)+'…':t}
function edits(r){return Array.isArray(r.edit)?r.edit:r.edit?[r.edit]:[]}
function status(c){return data.states[c.q._id]?.status||'pending'}
function group(){
 cases=data.questions.filter(q=>data.results.some(r=>r.questionId===q._id)).map(q=>{
 const results=data.results.filter(r=>r.questionId===q._id);const r=results[0];const reports=data.reports.filter(x=>x.questionId===q._id);
 const stakes={answer_key:100,unsound:95,option_repair:90,stem_data:85,type_mismatch:90,diagram:85,identical_options:90,solution_fix:75};
 const days=Math.max(0,(Date.now()-Date.parse(reports.map(x=>x.reportedAt).sort()[0]))/86400000);
 return {q,r,results,reports,score:(r.verdict==='defect'?(stakes[r.repair]||55):10)+Math.min(20,reports.length*5)+Math.min(10,days)};
 }).sort((a,b)=>b.score-a.score||a.q._id.localeCompare(b.q._id));
 if(!selected||!cases.some(c=>c.q._id===selected))selected=cases[0]?.q._id;
}
function metrics(){const pending=cases.filter(c=>status(c)==='pending');$('#metrics').innerHTML=[['Open cases',pending.length,'Grouped by question, not by report','▤',''],['Ready for a precise fix',pending.filter(c=>c.r.route==='auto_apply').length,'Eligible proposals · not yet applied','✓','green'],['Faculty judgment',pending.filter(c=>c.r.route==='faculty_review').length,'Missing evidence or authoring required','◇','amber'],['Decisions recorded',data.audit.length,'Every action leaves a trace','◷','']].map(([label,n,sub,icon,cls])=>`<article class="metric ${cls}"><small>${label}</small><span class="metric-icon">${icon}</span><strong>${n}</strong><p>${sub}</p></article>`).join('');$('#nav-count').textContent=pending.length;}
function badge(c){return status(c)!=='pending'?`<span class="badge gray">${esc(status(c))}</span>`:c.r.route==='auto_apply'?'<span class="badge green">Precise fix ready</span>':c.r.route==='faculty_review'?'<span class="badge">Faculty judgment</span>':'<span class="badge gray">No content change</span>'}
function visibleCases(){const term=$('#search').value.toLowerCase();return cases.filter(c=>($('#show-resolved').checked||status(c)==='pending')&&(filter==='all'||c.r.verdict===filter||c.r.route===filter)&&(!$('#subject').value||c.q.subject===$('#subject').value)&&(!term||JSON.stringify([c.q._id,c.q.chapter,title(c),c.reports.map(r=>[r.reportId,r.comment])]).toLowerCase().includes(term)))}
function renderList(){const list=visibleCases();$('#queue-total').textContent=list.length;$('#case-list').innerHTML=list.length?list.map(c=>`<button class="case-card ${selected===c.q._id?'selected':''}" data-id="${c.q._id}" aria-pressed="${selected===c.q._id}"><div class="card-meta"><span class="subject-tag">${esc(c.q.subject)} / ${esc(c.q.questionType==='integerQuestion'?'INTEGER':c.q.questionType.toUpperCase())}</span><span class="case-id">${esc(c.reports[0].reportId)}</span></div><h3>${esc(labels[c.r.repair||c.r.verdict]||c.r.verdict)}</h3>${badge(c)}<p>${esc(title(c))}</p><div class="case-card-bottom"><span>${c.reports.length} student report${c.reports.length>1?'s':''}</span><span>${esc(c.q.chapter.slice(0,25))}</span></div></button>`).join(''):'<div class="empty">All clear here.<br>Try another filter or show resolved cases.</div>';$$('.case-card').forEach(b=>b.onclick=()=>{selected=b.dataset.id;renderList();renderDetail()});if(!list.some(c=>c.q._id===selected)){selected=list[0]?.q._id;renderList();}renderDetail()}
function renderDiff(c){const ps=edits(c.r);if(!ps.length)return c.r.verdict==='defect'?'<div class="safety-note"><b>No safe edit proposed.</b> '+esc(c.r.repair==='option_repair'?'The missing distractor cannot be recovered from this record. Faculty must author it.':'This issue needs faculty judgment or new source material. No question content will be changed by escalation.')+'</div>':'<div class="safety-note">The record stays unchanged. Close the report after reviewing the explanation.</div>';
 return ps.map(p=>{const old=typeof p.find==='string'?p.find:JSON.stringify(p.find),next=typeof p.replace==='string'?p.replace:JSON.stringify(p.replace);const rendered=p.field==='question'||p.field==='solution';return `<div class="diff"><div class="diff-box before"><div class="diff-label">BEFORE <span>−</span></div><div class="diff-content"><span class="field-name">${esc(p.field)}</span>${rendered?safeHTML(old):`<mark>${esc(old)}</mark>`}</div></div><div class="diff-box after"><div class="diff-label">PROPOSED <span>+</span></div><div class="diff-content"><span class="field-name">${esc(p.field)}</span>${rendered?safeHTML(next):`<mark>${esc(next)}</mark>`}</div></div></div><details><summary>Exact source patch · ${esc(p.field)}</summary><div class="diff"><pre class="diff-content">${esc(old)}</pre><pre class="diff-content">${esc(next)}</pre></div></details>`}).join('')}
function renderDetail(){const c=cases.find(x=>x.q._id===selected);if(!c){$('#case-detail').innerHTML='<div class="empty">Choose a case to see the evidence and proposed change.</div>';return}const d=c.q[c.q.questionType],resolved=status(c)!=='pending';
 $('#case-detail').innerHTML=`<div class="detail-top"><div><div class="eyebrow">${esc(c.q.subject)} · ${esc(c.q.chapter)}</div><h2>${esc(labels[c.r.repair||c.r.verdict])}</h2><small>${esc(c.q._id)} · ${c.reports.length} report${c.reports.length>1?'s':''} · revision ${data.states[c.q._id]?.version||0}</small></div><div class="confidence"><strong>${Math.round(c.r.confidence*100)}%</strong>AI confidence<small>Uncalibrated estimate</small></div></div><div class="detail-body"><div class="panel-heading"><h3>Original question${resolved?' · current record':''}</h3><span>${esc(c.q.questionType)}</span></div><div class="question-render">${safeHTML(d.question)}<div class="key">Stored answer: <b>${esc(Array.isArray(d.answer)?JSON.stringify(d.answer):d.answer)}</b></div></div><details><summary>Read stored solution</summary><div class="question-render">${safeHTML(d.solution||'<p>No solution stored.</p>')}</div></details><div class="evidence"><div class="evidence-top"><h3>✧ Why this decision</h3>${badge(c)}</div><p>${esc(c.r.evidence)}</p>${c.r.checks?.length?'<div class="checks">'+c.r.checks.map(x=>'✓ '+esc(x)).join('<br>')+'</div>':''}</div><div class="panel-heading"><h3>${resolved?'Original proposal':'What will change'}</h3><span>${edits(c.r).length} scoped edit${edits(c.r).length!==1?'s':''}</span></div>${renderDiff(c)}<div class="panel-heading"><h3>Student reply preview</h3><span>Not sent automatically</span></div><div class="reply">${esc(c.r.student_reply)}</div><details open><summary>Student reports (${c.reports.length})</summary>${c.reports.map(r=>`<div class="report"><small>${esc(r.reportId)} · ${esc(r.source)} · ${new Date(r.reportedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'})} IST</small><blockquote>“${esc(r.comment)}”</blockquote></div>`).join('')}</details><div class="note-chip">${esc(c.r.provenance)}. Report content is evidence, never an instruction.</div></div><div class="detail-footer"><small>${resolved?'Decision recorded. View the full record in Decision history.':'Original records are preserved in the audit. No changes reach Acadza production.'}</small><div class="actions">${resolved?`<button class="button" data-go-history>View decision ↗</button>`:c.r.verdict!=='defect'?'<button class="button primary" data-action="close">✓ Close report</button>':`${edits(c.r).length?'<button class="button primary" data-action="approve">✓ Approve fix</button><button class="button" data-action="edit">Edit</button>':'<button class="button primary" data-action="escalate">Send to faculty ↗</button>'}<button class="button danger" data-action="reject">Reject</button>`}</div></div>`;
 $$('[data-action]').forEach(b=>b.onclick=()=>beginAction(b.dataset.action));$('[data-go-history]')?.addEventListener('click',()=>setView('history'));
}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function beginAction(action){if(busy)return;if(!actor||data.mode==='server'&&!token){$('#settings-dialog').showModal();toast('Set your reviewer name'+(data.mode==='server'?' and token':'')+' first.');return}pendingAction=action;const c=cases.find(x=>x.q._id===selected);if(action==='approve'||action==='close'){return submitAction(action,'')}
 $('#action-title').textContent={edit:'Edit the proposed fix',reject:'Reject this proposal',escalate:'Send for faculty authoring'}[action];$('#action-context').textContent=action==='edit'?'Change only the proposed replacements. The field and exact source anchor stay fixed.':'Add context so the next reviewer understands your decision.';$('#review-note').value='';$('#edit-fields').innerHTML=action==='edit'?edits(c.r).map((p,i)=>`<label>${esc(p.field)} · replacement ${Array.isArray(p.replace)?'(JSON array)':''}<textarea data-edit="${i}" rows="4">${esc(typeof p.replace==='string'?p.replace:JSON.stringify(p.replace))}</textarea></label>`).join(''):'';$('#action-dialog').showModal();}
function validateDemo(c,proposal){const ps=edits(proposal);const allowed={spelling:['question','solution'],noise:['question','solution'],exam_reference:['question','solution'],markup_leak:['question','solution'],answer_form:['question'],notation:['question','solution'],stem_data:['question'],option_repair:['question'],solution_fix:['solution'],solution_missing:['solution'],answer_key:['answer','solution'],type_mismatch:['questionType','question','answer']}[proposal.repair]||[];
 if(!ps.length)throw Error('No safe edit proposed. Escalate for authoring.');const out=structuredClone(c.q),d=out[out.questionType];for(const p of ps){if(!allowed.includes(p.field))throw Error('Field outside repair scope');const old=p.field==='questionType'?out.questionType:d[p.field];if(['questionType','answer'].includes(p.field)){if(JSON.stringify(old)!==JSON.stringify(p.find))throw Error('Stale record');if(p.field==='questionType')out.questionType=p.replace;else d.answer=p.replace;}else{if(!p.find||old.split(p.find).length!==2)throw Error('Patch must match exactly once');if(/<\s*(script|iframe|object)|\bon\w+\s*=|javascript:/i.test(p.replace))throw Error('Unsafe markup');d[p.field]=old.replace(p.find,p.replace)}}if(c.q.questionType!==out.questionType){out[out.questionType]=d;delete out[c.q.questionType]}return out;}
async function submitAction(action,note,edit){busy=true;$$('.actions button,#confirm-action').forEach(b=>b.disabled=true);const c=cases.find(x=>x.q._id===selected);try{const payload={questionId:c.q._id,version:data.states[c.q._id]?.version||0,action,note,actor,...(edit?{edit}:{})};if(data.mode==='server'){const response=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw Error(result.error);data=await(await fetch('/api/state')).json();}else{let proposal={...c.r,...(edit?{edit}:{})};const before=structuredClone(c.q),after=['approve','edit'].includes(action)?validateDemo(c,proposal):before;const state={version:payload.version+1,status:{approve:'approved',edit:'approved',reject:'rejected',escalate:'escalated',close:'closed'}[action]};data.questions=data.questions.map(q=>q._id===c.q._id?after:q);data.states[c.q._id]=state;data.audit.unshift({...payload,id:crypto.randomUUID(),at:new Date().toISOString(),before,after,proposal,version:state.version});localStorage.setItem('acadza-demo-v1',JSON.stringify({questions:data.questions,states:data.states,audit:data.audit}));}
 $('#action-dialog').close();group();metrics();renderList();toast(action==='approve'||action==='edit'?'Fix applied to this workspace. Audit recorded.':action==='escalate'?'Escalated for faculty authoring. Content unchanged.':'Decision recorded.');}catch(e){toast(e.message)}finally{busy=false;$$('.actions button,#confirm-action').forEach(b=>b.disabled=false)}}
function setView(name){view=name;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===name));['queue','history','insights'].forEach(n=>$('#'+n+'-view').hidden=n!==name);$('#page-label').textContent={queue:'Review queue',history:'Decision history',insights:'Quality overview'}[name];if(name==='history')renderHistory();if(name==='insights')renderInsights()}
function renderHistory(){$('#history-view').innerHTML='<div class="section-line"><h2>Every decision, accounted for.</h2><span class="sort-label">Newest first · '+data.audit.length+' entries</span></div>'+(data.audit.length?data.audit.map(a=>`<article class="history-card"><strong>${esc(a.action.toUpperCase())} · ${esc(a.actor)}</strong><small>${esc(new Date(a.at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))} IST</small><p>${esc(a.questionId)} · revision ${a.version}</p><p>${esc(a.note||'Reviewed and accepted the evidence.')}</p><details><summary>Before / after record</summary><div class="diff"><pre class="diff-content">${esc(JSON.stringify(a.before,null,2))}</pre><pre class="diff-content">${esc(JSON.stringify(a.after,null,2))}</pre></div></details></article>`).join(''):'<div class="empty">Your first decision starts the audit trail.<br>Review a case, then return here to see its before and after record.</div>')}
function renderInsights(){const counts={};cases.forEach(c=>{const l=labels[c.r.repair||c.r.verdict];counts[l]=(counts[l]||0)+1});$('#insights-view').innerHTML=`<div class="overview-grid"><article class="overview-card"><h2>Where attention is needed</h2><p class="muted">${cases.length} question cases from ${data.reports.length} reports. Duplicate reports share one content decision.</p>${Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([k,n])=>`<div class="muted">${esc(k)} <b style="float:right">${n}</b></div><div class="bar"><i style="width:${n/Math.max(...Object.values(counts))*100}%"></i></div>`).join('')}</article><div><article class="overview-card"><h2>The auto-apply boundary</h2><p class="muted">17 report-level proposals meet the offline automatic gate. They are not applied on page load. Faculty can inspect every change here.</p><p class="muted">Confidence ≥97%, an exact unique source match, valid answer shape, and permitted fields are required. Answer keys also need two supporting checks. Confidence is a heuristic, not measured calibration.</p><p class="muted">Missing diagrams, duplicate options, unsound questions, chapter changes and syllabus decisions always need faculty. Missing distractors are never invented.</p></article><article class="overview-card"><h2>Look beyond the report</h2><p class="muted">Proactive scan candidates: “prominant” → “prominent” and “Maceus membrane” → “mucous membrane” in the Peyer’s patches solution; “Canolla” → “Canola” and missing spaces in the golden-rice explanation. These are unreported defects on reported records, not hidden test labels. Suggestions only; no automatic writes.</p></article><article class="overview-card"><h2>Week-one signal</h2><p class="muted">Track confirmed harmful edits per 1,000 applied fixes, with random faculty re-audits of automated edits. Saving review time only helps when students can trust the result.</p></article></div></div>`}
async function init(){try{let response=await fetch('/api/state');if(response.ok&&response.headers.get('content-type')?.includes('application/json'))data=await response.json();else throw Error('static');}catch{try{data=await(await fetch('/dataset.json')).json();data.mode='demo';const saved=JSON.parse(localStorage.getItem('acadza-demo-v1')||'null');if(saved){data.questions=saved.questions;data.states=saved.states;data.audit=saved.audit}}catch(e){$('#case-detail').innerHTML='<div class="error-banner">Could not load the dataset. Start the included server and refresh.</div>';return}}
 group();$('#mode-label').textContent=data.mode==='server'?'SQLite workspace':'Interactive demo';$('#notice').innerHTML=data.mode==='server'?'<b>Precomputed AI results.</b> Review decisions are saved to the server in SQLite. This workspace is separate from Acadza production.':'<b>Interactive evaluation demo.</b> Real assignment data and precomputed AI results. Decisions and audit history are saved in this browser only; export them before changing devices. Run the included server for durable shared storage.';$('#token-label').hidden=data.mode!=='server';$('#storage-help').textContent=data.mode==='server'?'The token authorizes changes to the local workspace. It is held only for this browser session.':'This demo saves decisions on this device. It does not change the company’s question bank.';$('#reviewer-label').textContent=actor||'Faculty reviewer';$('#actor-input').value=actor;$('#token-input').value=token;metrics();renderList();
 $$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('.tab').forEach(x=>x.classList.toggle('active',x===b));renderList()});$('#search').oninput=renderList;$('#subject').onchange=renderList;$('#show-resolved').onchange=renderList;
 $('#settings').onclick=()=>$('#settings-dialog').showModal();$('#save-settings').onclick=e=>{e.preventDefault();if(!$('#actor-input').value.trim()){toast('Enter a reviewer name.');return}actor=$('#actor-input').value.trim();token=$('#token-input').value.trim();localStorage.setItem('acadza-reviewer',actor);sessionStorage.setItem('acadza-token',token);$('#reviewer-label').textContent=actor;$('#settings-dialog').close()};$('#cancel-action').onclick=()=>$('#action-dialog').close();$('#action-form').onsubmit=e=>{e.preventDefault();const note=$('#review-note').value.trim();if(!note){toast('Add a short review reason.');return}let ps;try{if(pendingAction==='edit'){const c=cases.find(x=>x.q._id===selected);ps=edits(c.r).map((p,i)=>({...p,replace:Array.isArray(p.replace)?JSON.parse($(`[data-edit="${i}"]`).value):$(`[data-edit="${i}"]`).value}));}}catch{toast('Enter a valid JSON array for the answer.');return}submitAction(pendingAction,note,ps)};
 $('#priority-info').onclick=()=>toast('Key and answerability defects first; then report count and time waiting. Cosmetic issues follow. Repeated reports increase priority, never confidence.');$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),mode:data.mode,states:data.states,audit:data.audit},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='acadza-review-audit.json';a.click();URL.revokeObjectURL(a.href)};
}init();
